for(const c of ['#203d48','#171c24','#c14f43','#d69b28','#517a58','#4877a3','#8a63a2','#f2eee3']){const b=document.createElement('button');b.style.background=c;b.dataset.color=c;b.setAttribute('aria-label','Colour '+c);b.setAttribute('aria-pressed','false');b.onclick=()=>setColor(c);$('swatches').append(b);}
$('color').onchange=()=>setColor($('color').value);for(const id of ['hue','saturation','lightness'])$(id).oninput=()=>{settings.color=hslToHex(Number($('hue').value),Number($('saturation').value),Number($('lightness').value));$('color').value=settings.color;$('hue-value').value=$('hue').value+'°';for(const sw of $('swatches').children)sw.setAttribute('aria-pressed',String(sw.dataset.color===settings.color));sample();};
for(const [id,min,max,key,divisor] of [['size',1,40,'size',1],['opacity',0,100,'opacity',100]])for(const control of [id,id+'-number'])$(control).addEventListener(control===id?'input':'change',()=>{const value=Number($(control).value);if(!Number.isFinite(value)||value<min||value>max||$(control).value===''){status('Value must be '+min+' to '+max,true);$(control).value=settings[key]*divisor;return;}settings[key]=value/divisor;$(id).value=value;$(id+'-number').value=value;sample();});
$('brush').onchange=()=>{settings.brush=$('brush').value;sample();};for(const id of ['pen','eraser','pan'])$(id).onclick=()=>{if(active)return;tool=id;for(const name of ['pen','eraser','pan'])$(name).setAttribute('aria-pressed',String(name===id));$('brush-controls').hidden=id==='eraser';$('eraser-controls').hidden=id!=='eraser';};
$('undo').onclick=()=>act(()=>undo(h));$('redo').onclick=()=>act(()=>redo(h));$('title').onchange=()=>act(()=>command(h,b=>b.title=$('title').value));$('add-layer').onclick=()=>editLayer('add');
for(const id of ['paper','paper-color','spacing'])$(id).onchange=()=>act(()=>command(h,b=>{b.paper.kind=$('paper').value;b.paper.color=$('paper-color').value;b.paper.spacing=Number($('spacing').value);}));
$('panels').onclick=()=>{const open=$('inspector').dataset.open!=='true';$('inspector').dataset.open=String(open);$('panels').setAttribute('aria-expanded',String(open));};$('close-panels').onclick=()=>{$('inspector').dataset.open='false';$('panels').setAttribute('aria-expanded','false');};
const pos=e=>{const r=canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};};
const point=e=>({...toDocument(pos(e).x,pos(e).y,view),pressure:e.pointerType==='pen'?Math.max(0,Math.min(1,e.pressure)):null});
function report(e){$('input').textContent=e.pointerType==='pen'?'Pen · reported pressure '+e.pressure.toFixed(2):e.pointerType==='touch'?'Touch · navigation only':'Mouse · pressure unavailable';}
function cancel(){if(active?.erase)status('Eraser gesture cancelled');active=null;contacts.clear();refresh();}
