async function newBoard(){const b=createBoard();expected=await store.save(b,0);h=createHistory(b);saved=0;view={x:0,y:0,scale:1};status('Saved on this device');refresh();panels();}
$('new').onclick=()=>transition(newBoard);$('boards').onclick=async()=>{if(!store)return;try{const records=await store.list();$('board-list').replaceChildren();for(const r of records){const row=document.createElement('div');row.className='board-row';const btn=document.createElement('button');btn.textContent=r.current?.title||'Damaged board';btn.onclick=()=>transition(async()=>{await openBoard(r.id);$('gallery').close();});row.append(btn);$('board-list').append(row);}$('gallery').showModal();}catch(e){status(e.message,true);}};$('close-gallery').onclick=()=>$('gallery').close();
